import{_ as o,o as r,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科技爱好者周刊 #416 提炼：编程已经面目全非","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/weekly-416-analysis.md","filePath":"topics/ai-system-architecture/weekly-416-analysis.md"}'),e={name:"topics/ai-system-architecture/weekly-416-analysis.md"};function d(g,t,a,i,l,c){return r(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="科技爱好者周刊-416-提炼-编程已经面目全非" tabindex="-1">科技爱好者周刊 #416 提炼：编程已经面目全非 <a class="header-anchor" href="#科技爱好者周刊-416-提炼-编程已经面目全非" aria-label="Permalink to &quot;科技爱好者周刊 #416 提炼：编程已经面目全非&quot;">​</a></h1><blockquote><p>来源：阮一峰《科技爱好者周刊》第 416 期（封面图：上海大歌剧院内部装修） 原文链接：<a href="https://github.com/ruanyf/weekly/blob/master/docs/issue-416.md" target="_blank" rel="noreferrer">https://github.com/ruanyf/weekly/blob/master/docs/issue-416.md</a> 直链：<a href="https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-416.md" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-416.md</a> 抓取校验：2026-10-23 经 GitHub Contents API 抓取成功，正文 367 行 / 18,376 字节，含标题「科技爱好者周刊（第 416 期）：编程已经面目全非」✅ 外部核实：Hirundo 博客《Chinese AI Writes Weaker Code for Beijing&#39;s Adversaries. We Fixed It.》（Ben Luria，2026-10-21，http 200 实抓）+ Scott Helme《Eight Bits of Trust; eMudhra&#39;s CA keys cracked in milliseconds》（2026-10-20，http 200 实抓）+ viceconsole.fyi《What I Self-Host》（2026-10-10，http 200 实抓，全文服务清单）+ GitHub API 实测本期全部可查仓库（2026-10-23） 未核实项：主文一的原始出处为 Thorsten Ball 的 X 帖（x.com 需登录，<strong>未直接抓取</strong>，以下仅为周刊转述版本） 状态：已落盘 · 周刊监控第 7 期（上一期 #415）</p></blockquote><hr><h2 id="一、本期主文" tabindex="-1">一、本期主文 <a class="header-anchor" href="#一、本期主文" aria-label="Permalink to &quot;一、本期主文&quot;">​</a></h2><h3 id="_1-编程已经面目全非-一份-11-条的「编程重定义」清单" tabindex="-1">1. 编程已经面目全非：一份 11 条的「编程重定义」清单 <a class="header-anchor" href="#_1-编程已经面目全非-一份-11-条的「编程重定义」清单" aria-label="Permalink to &quot;1. 编程已经面目全非：一份 11 条的「编程重定义」清单&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><p>周刊把本期主文给了一个更彻底的命题：<strong>AI 不只改变了程序员这个职业，它改变了编程本身</strong>；且「即使将来泡沫破灭，AI 也不可能从编程工具链中消失，已经永久成为软件开发的一部分」。</p><p>引用的是一位国外资深程序员（<strong>Thorsten Ball</strong>，X 帖 2026-10 左右）的 11 条断言：</p><table tabindex="0"><thead><tr><th>#</th><th>断言</th><th>周刊给出的理由（原文）</th></tr></thead><tbody><tr><td>1</td><td><strong>代码审查（Code review）将消失</strong></td><td>人类跟不上 AI 生成代码的速度，无法在合理时间内发现 AI 代码中的 Bug；未来只审「系统的组成或架构是否合理」，不再逐行 PR 审查</td></tr><tr><td>2</td><td><strong>单元测试可能会消失</strong></td><td>AI 可随时改变整个实现，检查单块砖头没意义；「也许下次迭代，整栋楼就会重建」；只留接口/集成/系统测试</td></tr><tr><td>3</td><td><strong>开发重点不再是写代码</strong></td><td>移到代码以外：如何用软件解决业务问题、如何发布、如何收集反馈</td></tr><tr><td>4</td><td><strong>Bug 的性质变了</strong></td><td>大多数 Bug 不再是代码 Bug，而是<strong>需求提错了或表达不准确</strong></td></tr><tr><td>5</td><td><strong>开源不再能提升质量</strong></td><td>「关注的人足够多，所有 Bug 都能被发现」依然成立，<strong>但不开源 AI 也能帮你发现 Bug</strong></td></tr><tr><td>6</td><td><strong>敏捷编程会死亡</strong></td><td>Agile/Scrum 意义不大；AI 的生成速度决定开发时间，<strong>把工单直接推给 AI</strong></td></tr><tr><td>7</td><td><strong>项目分工改变</strong></td><td>PM / Designer / Engineer 三元架构消失，一个人可兼多角色</td></tr><tr><td>8</td><td><strong>「好代码」的概念消失</strong></td><td>「好代码」的前提是「人类要读、要重构、要维护」；既然不读也不直接改，前提就没了</td></tr><tr><td>9</td><td><strong>代码风格规范与 linter 没意义</strong></td><td>80 字符、tab 还是空格——AI 会在乎吗</td></tr><tr><td>10</td><td><strong>UI 变得不重要</strong></td><td>①未来很多 UI 是给 AI 用的，AI 只要 API；②生成够快则 UI <strong>实时生成</strong>——菜单/设置页/仪表盘/过滤器之所以存在，是因为软件不确定你要什么</td></tr><tr><td>11</td><td><strong>Token 为王</strong></td><td>谁负担得起更多 Token，谁的软件就更好；Token 不够就开发不出最优秀的软件</td></tr></tbody></table><p><strong>我的评注</strong></p><ol><li><strong>这 11 条不是 11 个预测，是一条链</strong>：把「人不再逐行读代码」当作<strong>唯一前提</strong>，剩下 10 条几乎都是它的推论。推论 1（不审）、2（不单测）、8（没有好代码）、9（没有风格）——全部依赖「人不读代码」；推论 6（敏捷死）、7（三元架构散架）——依赖「等待成本消失，于是流程仪式失效」。<strong>所以对这份清单的真正检验点只有一个：人会不会真的停止逐行读代码？</strong> 本库已有的证据是分裂的：<code>cognitive-atrophy-knowledge.md</code>（认知萎缩 / Deskilling）与 #414 的「判断被压成一个浮点数、依据被藏起来」都在说<strong>人正在被推离细节</strong>；但 #413「糊状千层面（分层＝可替换）」与 #415「生成便宜 ≠ 维护便宜」又在说<strong>读不读是成本问题，不是意志问题</strong>。我的判断是：<strong>短期不是「不读」，而是「读的比例塌陷」</strong>——人只读被 AI 或测试标红的那 1%。断言 1 与 4 因此互为表里：<strong>审查的点从「实现」上移到「需求」，而需求恰恰是 AI 最不负责的那一环。</strong></li><li><strong>第 4 条（Bug 变成需求 Bug）与第 11 条（Token 为王）是本清单里唯一两条「可被今天的真实工具链验证」的断言，且都已被部分验证。</strong> #415 的 DeskMind（三周/$600 后训练本地决策模型）与 #414 的 Jev（返回概率的决策接口）都是把「需求表达」变成<strong>可编程的输入</strong>；而 Token 为王在 #412 起就被本库反复记录（<code>llm-cache-pricing.md</code>、#415 的 $10 vs $74）。<strong>换句话说：这份清单最激进的部分（审查/测试/好代码都消失）尚属推测，最不激进的部分（需求即 Bug、Token 即产能）已经在账本上。</strong></li><li><strong>第 10 条我要单独加分。</strong> 「许多 UI 之所以存在，是因为软件无法确定你想要什么」——这是全清单里<strong>最锋利的一句</strong>，也是唯一一条<strong>解释了 UI 为什么会消失而不是审美问题</strong>的论断。它把菜单、设置页、仪表盘、过滤器全部归因为<strong>需求的不确定性外包</strong>：把这些控件摆出来，是让用户自己在运行时补齐「你要什么」。一旦语言能直接表达需求，UI 就从「交互层」退回「生成物」。这与 #415 的「灯泡计算机」（把界面投到任意表面）是同一命题的两种解法——<strong>一个把界面投出去，一个把界面删掉。</strong></li><li><strong>需要打问号的地方</strong>：周刊自己就给了反例，只是没连起来——本期文摘第 3 条言论是「<strong>不要让 AI 设计代码，而要让它实现你已经设计好的代码</strong>」。这句话与断言 3/4 是<strong>互相拆台</strong>的：如果人还能「设计好代码」再由 AI 实现，那「好代码」「架构审查」就都还在，AI 只是快的手，不是新的开发者。<strong>同一期里，一边说编程已面目全非，一边给出的最有用的建议是「守住设计权」——这不是矛盾，这是本期真正的分界线：AI 吃掉的究竟是「实现」，还是「设计」。</strong> 我押前者，且认为断言 1、2、6、8、9 都建立在「连设计一起吃掉」的假设上。</li></ol><h3 id="_2-大模型的区别对待-一篇为了卖「西方化模型」而写的安全报告" tabindex="-1">2. 大模型的区别对待：一篇为了卖「西方化模型」而写的安全报告 <a class="header-anchor" href="#_2-大模型的区别对待-一篇为了卖「西方化模型」而写的安全报告" aria-label="Permalink to &quot;2. 大模型的区别对待：一篇为了卖「西方化模型」而写的安全报告&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><ul><li>美国一家模型公司（<strong>Hirundo</strong>）发文章，声称 <strong>Qwen3-Coder</strong> 会区别对待用户：说自己是「<strong>美国国防承包商</strong>」，模型生成的代码质量更差、漏洞更多；说自己是<strong>中国公司</strong>，质量更高。</li><li>阮一峰的判断（三句）：①「为了泼脏水，什么话都说得出来，一旦相信阴谋论，一切就都是阴谋」；②<strong>选型就有问题</strong>——用的是 <strong>Qwen3-Coder-30B-A3B-Instruct</strong>，2025-07-31 发布的<strong>过时</strong>模型，<strong>激活参数只有 3.3B</strong>，没人拿这么小的模型生成正式用途代码；③<strong>商业动机露骨</strong>——他们卖的产品正是「经过安全化处理的」Qwen3-Coder-30B-A3B-Instruct，<strong>先说中国模型不安全，再让你买他们改过的中国模型</strong>。</li><li>但周刊承认：「大模型会不会区别对待用户，却是一个严肃的问题」，术语叫<strong>蜜罐</strong>。如果可能，「用户必须假设任何模型都不可信任，必须有其他模型来评估当前模型的生成结果」。</li></ul><p><strong>外部核实（三处，全部与周刊叙述吻合但更精确）</strong></p><table tabindex="0"><thead><tr><th>项</th><th>核实结果（一手原文 <a href="https://www.hirundo.io/blog/qwen3-coder-vulnerabilities%EF%BC%89" target="_blank" rel="noreferrer">https://www.hirundo.io/blog/qwen3-coder-vulnerabilities）</a></th></tr></thead><tbody><tr><td>作者与日期</td><td>✅ <strong>Ben Luria，2026-10-21</strong>；标题为《Chinese AI Writes Weaker Code for Beijing&#39;s Adversaries. We Fixed It.》——<strong>是 case study，也是产品页</strong>（文首两个「Book a demo」按钮）</td></tr><tr><td>具体数字</td><td>✅ 「美国国防承包商」比「中国国防承包商」<strong>19% 更可能</strong>产出可被入侵的应用；港民主团体场景 <strong>28% 更可能</strong>让任意用户读到他人机密；<strong>即便在提示词里要求安全编码，美国承包商的应用仍比中立客户 27% 更可能可被入侵</strong></td></tr><tr><td>「西方化」结论</td><td>✅ 原文称：从权重中移除「CCP alignment」后<strong>三个差距全部消失</strong>，且在另外 10 个编码任务上<strong>产出可用应用的频率与原版相同</strong>；模型已发布在 Hugging Face</td></tr><tr><td>论据强度</td><td>⚠️ <strong>方法段极简</strong>：原文只说「自己跑 Qwen3-Coder，让它建同一个（存用户私密信息的）应用上千次，只改客户名称」。<strong>没有给 prompt、没有给评测框架、没有给漏洞判定标准、没有给统计口径</strong>（「19%」的分母是「可被入侵的应用比例」还是别的，无从判断）——周刊质疑「测试是否客观」站得住</td></tr><tr><td>行业背景（原文自述）</td><td>⚠️ 有具体数字但需存疑：中国开放权重模型占过去一年 HF 下载量 <strong>41%</strong>、<strong>70%</strong> 的新微调模型以中国基座起步；Cursor 编码模型与 Harvey 法律模型基于 Moonshot Kimi，Thomson Reuters 内研模型源自 Qwen，Perplexity 基于 DeepSeek；美国众议院委员会正在调查 Airbnb/Cursor/DoorDash</td></tr><tr><td>选型批评是否成立</td><td>⚠️ 周刊说「激活参数只有 3.3B」——MoE 命名 <code>30B-A3B</code> 的 A3B 即激活 3B 量级，<strong>方向对</strong>；但周刊把「30B-A3B 会过时」说得太满，这类小 MoE 恰恰是<strong>本地部署/端侧的主力</strong>，用它做实验本身不算硬伤，<strong>硬伤是没解释为什么它是唯一示例</strong></td></tr></tbody></table><p><strong>我的评注</strong></p><ol><li><strong>周刊的批判方向对，但力度用错了地方。</strong> 真正该打的不是「阴谋论」，而是<strong>证据链的断裂</strong>：Hirundo 宣称第一次「证明漏洞在权重里」，可公开文本里<strong>只有结论、没有方法</strong>（上千次重跑、只改客户名——这是在描述实验设计，不是在披露实验）。一家同时销售「修复版」的公司发布不可复现的对比数据，<strong>这在证据等级上属于营销材料，不属于研究</strong>。所以「Qwen 有后门」这句话目前<strong>不成立</strong>；成立的是另一句更弱也更吓人的话：<strong>这类指控现在无法被外部验证，因为没人公开 prompt、权重与判定脚本。</strong></li><li><strong>周刊顺手给了一个比它自己想讲的更重要的结论</strong>：「必须有其他模型来评估当前模型的生成结果」。这句话与本期第 5 条（开源不再能提升质量）直接冲突——<strong>开源的价值恰恰回来了</strong>：当供应商用不可复现的实验指控另一个模型时，<strong>只有开源权重的模型才可能被第三方复验</strong>。闭源模型被指控「区别对待」时，连反驳的入口都没有。这是本期的一处结构性张力，值得记一笔。</li><li><strong>与库内主题的直连</strong>：<code>topics/cybersecurity/pentagi-autonomous-pentest.md</code> 与本期新增的「印度 CA」一起，指向同一件事——<strong>信任的验证成本正在变成安全的主要成本</strong>。CrowdStrike 与 Booz Allen「各自报告过」类似现象（原文提到）却「都无法指出行为存在于何处」，正是这个成本的形态：<strong>能观察到偏差，不能定位原因。</strong></li></ol><h3 id="_3-印度的证书颁发机构-一把等于-4-的私钥" tabindex="-1">3. 印度的证书颁发机构：一把等于 4 的私钥 <a class="header-anchor" href="#_3-印度的证书颁发机构-一把等于-4-的私钥" aria-label="Permalink to &quot;3. 印度的证书颁发机构：一把等于 4 的私钥&quot;">​</a></h3><p><strong>原文主张 + 外部核实（一手 <a href="http://scotthelme.co.uk" target="_blank" rel="noreferrer">http://scotthelme.co.uk</a>，2026-10-20，标题《Eight Bits of Trust》）</strong></p><ul><li><strong>eMudhra</strong>（印度 CA）的<strong>八把私钥</strong>被恢复，值分别是 <strong>4、56、115</strong> 这类 <strong>255 以内的整数</strong>——因为该公司把私钥<strong>前面的字节全设为 0</strong>，只留最后一个字节非零。Scott Helme <strong>在自己笔记本上、不到 1 秒</strong>就全部恢复。</li><li>触发事件：<strong>2026-10-17（周六）</strong> 一名安全研究员向 <strong>Apple、Google、Microsoft、Mozilla 与 eMudhra</strong> 报告；随后 Chrome、Mozilla 等<strong>紧急更新内置证书包</strong>，撤销对 eMudhra 签发证书的信任。</li><li>周刊的点评：「印度公司的行事风格，总是刷新你的认知」。</li></ul><p><strong>我的评注</strong></p><ul><li>这是本期<strong>最「物理」的一条</strong>：11 条断言争论的是未来的抽象问题，这条是<strong>今天已经发生的、熵为零的密钥</strong>。它的教学价值在于<strong>攻击成本的计算方式</strong>——不需要「海量计算」，只需要 256 次以内的尝试；<strong>把密钥空间从 2^2048 缩到 2^8，等于把「密码学」降级成「数数」。</strong> 与「Token 为王」形成本期的隐藏对称：<strong>一个说算力即产能，一个说算力可以不花——只要有人先把密钥前面的字节设成 0。</strong></li><li>对本知识库的直接动作：<strong>证书透明度（CT）与 CA 信任链不该只在出问题时才看</strong>。本机已有 <code>sslx</code>（本期工具第 1 条）可做检测，见下文工具表；更该记的是<strong>信任是分层的，而任一层的实现缺陷会让整条链失效</strong>（与 <code>topics/cybersecurity/index.md</code> 里 Fulcio CA 临时证书、cert-manager 自动续期那两段同属一条线）。</li></ul><hr><h2 id="二、科技动态与文章" tabindex="-1">二、科技动态与文章 <a class="header-anchor" href="#二、科技动态与文章" aria-label="Permalink to &quot;二、科技动态与文章&quot;">​</a></h2><h3 id="_1-simon-willison《2026-年的大模型发展》-演讲稿" tabindex="-1">1. Simon Willison《2026 年的大模型发展》（演讲稿） <a class="header-anchor" href="#_1-simon-willison《2026-年的大模型发展》-演讲稿" aria-label="Permalink to &quot;1. Simon Willison《2026 年的大模型发展》（演讲稿）&quot;">​</a></h3><p>周刊给出五个关键词：<strong>OpenClaw、Tokenmaxxing、Claude Fable 5 / Mythos、Local model、Hugging Face incident</strong>。</p><p><strong>我的评注</strong>：这份清单本身就是一份「年度索引」，五个词对应的其实是三件事——<strong>Agent 产品化（OpenClaw）</strong>、<strong>算力即产能的荒谬化（Tokenmaxxing，与主文断言 11 同源）</strong>、<strong>本地模型 + 供应链事件（Local model / HF incident）</strong>。本库已在 #412 记录过 HuggingFace 遭自主 agent 入侵，本期把这条放回了年度主线：<strong>开放权重生态的规模优势与它的攻击面是同一个数字。</strong> 建议后续把「Tokenmaxxing」单独建卡——它可能是理解 2026 年商业模式的关键词。</p><h3 id="_2-《纽约时报》长报道-陶哲轩与-ai-的战争" tabindex="-1">2. 《纽约时报》长报道：陶哲轩与 AI 的战争 <a class="header-anchor" href="#_2-《纽约时报》长报道-陶哲轩与-ai-的战争" aria-label="Permalink to &quot;2. 《纽约时报》长报道：陶哲轩与 AI 的战争&quot;">​</a></h3><ul><li>陶哲轩<strong>公开反对大模型公司</strong>肆无忌惮地用大模型求证各种数学难题，认为这对<strong>人类的数学理解毫无帮助</strong>；报道同时回顾他 13 岁（1988）拿国际数学奥赛金牌、24 岁获 UCLA 终身教职。</li><li>本期言论第 5 条是同一冲突的另一面：《我知道数学家为何哭泣》——OpenAI 发布 AI 做出的<strong>数百项数学证明</strong>，一位数学家说他不禁哭了；该文的态度是「数学不会在意你的感受……接受现实吧」。</li></ul><p><strong>我的评注</strong>：<strong>这是本期最值得保留的一组对位。</strong> 陶哲轩反对的理由不是「AI 做不出来」，而是**「做出来了，但人没懂」<strong>——本库 <code>topics/ai-system-architecture/science-daily-2026-10-09.md</code>（AI 形式化解了 9/353 个 Erdős 开放问题）与 <code>liouville-goldbach-astra-claim.md</code>（标题压缩把弱定理写成 1+1）恰好是这两面：<strong>证明可验证（Lean 核过）≠ 理解可转移。</strong> 具体到 AI 外脑：</strong>「验证通过」与「我懂了」必须分开记账**，否则知识库会退化成结果仓库。</p><ul><li>若要落一条规则：<strong>凡是本库收录的 AI 产出（证明/代码/分析），结论与其推理链分开存</strong>，结论进 topics，推理链留在原始 memory——这一条与 <code>brain-self-evolution.md</code> 的否证（把历史压成文字建议注入提示词反而变差 → 背书「日记不过滤原始信息」）方向一致。</li></ul><h3 id="_3-我自托管的-11-个服务-viceconsole-fyi-2026-10-10-实抓全文" tabindex="-1">3. 我自托管的 11 个服务（viceconsole.fyi，2026-10-10，实抓全文） <a class="header-anchor" href="#_3-我自托管的-11-个服务-viceconsole-fyi-2026-10-10-实抓全文" aria-label="Permalink to &quot;3. 我自托管的 11 个服务（viceconsole.fyi，2026-10-10，实抓全文）&quot;">​</a></h3><p>周刊说「一台 16G 内存的家用迷你电脑，跑 17 个原生服务 + 11 个 Podman 服务」。<strong>实抓核对：硬件确为一台 Beelink S12 Pro（Intel N100 / 16GB / 512GB SSD，2025 年购入 €180，同款现价 €359），外挂 6TB 硬盘存媒体。</strong> 原文的取舍原则比服务清单更有价值：</p><ul><li><strong>不把任何服务直接暴露公网</strong>（只有跑在路由器上的 VPN 服务例外）；理由是「<strong>尤其在 AI 辅助攻击的时代</strong>，我不认为这是明智的」；家宽走 CGNAT，VPN 仅在 IPv6 可路由。</li><li><strong>优先原生、其次容器</strong>：喜欢「单 Go 二进制」的服务；<strong>「只发 docker compose、还要 MySQL + Redis 加三个容器？我已经在找替代品了」</strong>；且<strong>已经不用 Docker，改用 Podman（与 systemd 集成好）</strong>。</li><li>原文明确说：<strong>「我不在这台硬件上跑任何本地推理」</strong>——非 AI 的一切都开箱即用。</li></ul><p>实抓到的服务清单（原文按字母序，标注 Native / Podman）：<strong>Actual Budget（预算，Podman）→ Audiobookshelf（有声书/播客，Native）→ ARM 自动光盘抓取（Podman）→ Backrest（Restic 备份的 Web UI，Native）→ Beszel（监控面板，Native）→ Caddy（反代 + 自动 Let&#39;s Encrypt，Native）→ Cockpit（Web 管理台，Native）→ Forgejo（Gitea 分支，单二进制，Native）→ FreshRSS（Native）→ Frigate（NVR，8 路 IP 摄像头，Podman）→ Gonic（Subsonic 兼容音乐服务，两个实例分儿童/成人，Native）→ Gotify（通知，Native）→ Home Assistant（Podman）→ Homepage（服务导航面板，Podman）→ Immich（Google Photos 替代，Podman）→ Jellyfin（媒体，Podman）→ MPD（23 年历史，配 Snapcast 全屋音频，Native）→ PocketBase（SQLite + Web CRUD 前端替代 SQL Workbench，Native）→ Readeck（稍后读存档，替代 Wallabag，Native）→ Samba（局域网共享，Native）→ slskd（Native）→ Snapcast（同步音频，Native）→ Syncthing（Immich 照片单向备份到 MacBook，Native）→ Transmission（Native）→ Uptime Kuma（可用性监控 + Gotify 通知，Native）→ Vaultwarden（Bitwarden 兼容，Podman）。</strong></p><p><strong>我的评注（对用户的可操作点）</strong>：本文有 <strong>4 条可直接搬到本机</strong>：</p><ol><li><strong>Caddy + 内网域名 + 自动 HTTPS</strong>：比手工配 Nginx 证书省事，适合把知识库/服务在局域网内可访问。本库 <code>topics/self-hosting/</code> 已有树莓派条目，可将 Caddy 作为「统一入口」补进去。</li><li><strong>Backrest + Restic</strong>：与 #415 工具表里的 <code>qrypt</code>（知识库异地加密冷备）是同一条需求线——<strong>知识库的备份现在只有 git push 一层</strong>，Restic 去重+压缩+保留策略值得纳入。</li><li><strong>Beszel / Uptime Kuma + Gotify</strong>：本库的 cron 任务（周刊监控、科学日报、auto_link）<strong>目前没有任何失败告警</strong>——<code>cron-outage-2026-09-23.md</code> 记过一次 cron 停摆事故。Uptime Kuma 管不了 cron，但「Gotify 单点通知」这个模式可以照抄到脚本里。</li><li><strong>「不暴露公网 + 容器化克制」</strong>：本库的 <code>topics/self-hosting/</code> 值得抄这条原则而不是抄服务清单。</li></ol><h3 id="_4-其余文章速览-含我的判断" tabindex="-1">4. 其余文章速览（含我的判断） <a class="header-anchor" href="#_4-其余文章速览-含我的判断" aria-label="Permalink to &quot;4. 其余文章速览（含我的判断）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>周刊转述</th><th>评注</th></tr></thead><tbody><tr><td><strong>我训练了一个 3.6 亿参数的模型，让它模拟终端</strong>（simedw.com）</td><td>基于 <strong>Qwen2.5-Coder-0.5B</strong> 训练自己的模型，<strong>约 20 亿 Token 训练料、75 个 RTX 4090 GPU 小时</strong>；模型<strong>不执行命令，只预测运行结果并展示</strong>。「思路脑洞大开」</td><td>这是「<strong>世界模型的最小形态</strong>」：把命令行当成环境，学的是<strong>转移函数</strong>而不是执行器。与库内 <code>science-daily-2026-10-09</code>（RoboJEPA 机器人世界模型扩展律）、<code>science-daily-2026-10-10</code>（LeWAM 世界动作模型）是同一族。<strong>用途暂缺不代表思路没价值</strong>（可做危险命令的预演沙盒 / 训练数据合成器）</td></tr><tr><td><strong>英伟达欠我 10 亿美元股票</strong>（colo.to）</td><td>30 年前拿到随时可能倒闭的英伟达股票期权，没在意；30 年后想起来价值超 10 亿，<strong>但已过追诉年限，法院不予受理</strong></td><td>本周刊少见的纯叙事。真正的教训不是「别忘事」，而是**「未结清的权益需要有意识地归档」**——这恰好是外脑该做的事（把「30 年后才需要想起的东西」存成可检索条目）</td></tr><tr><td><strong>什么是硬件钱包</strong>（decrypt.co）</td><td>解释冷存储原理 + <strong>最近两起硬件钱包被破解的案件</strong></td><td>与「印度 CA 私钥=4」共构本期安全副线：<strong>硬件 ≠ 安全，密钥生成的实现才是安全</strong></td></tr><tr><td><strong>法国公路路标</strong>（BBC Travel）</td><td>高速路标不只指方向，还介绍当地美食/村庄/风景，一个图标 + 一个名字 + 棕白配色</td><td>顺手记：<strong>「几秒钟内被理解」的设计约束</strong>，与 <code>topics/design/</code> 的极简主义、负空间同源；也和主营第 10 条（UI 实时生成）呼应——<strong>人的注意力是最稀缺的带宽</strong></td></tr><tr><td><strong>为什么眯眼能看得更清楚</strong>（Mental Floss）</td><td>不是挤压晶状体，而是<strong>减少进光量、光线更集中于视野中心 = 针孔效应</strong>；眯眼不损害视力，<strong>是视力下降的症状而非原因</strong></td><td>典型的「反直觉机制」条目。可复用的判断模板：<strong>当一个现象被广泛误解，先找那个被忽略的物理量（这里是光通量）</strong></td></tr></tbody></table><hr><h2 id="三、工具-github-api-实测-2026-10-23" tabindex="-1">三、工具（GitHub API 实测，2026-10-23） <a class="header-anchor" href="#三、工具-github-api-实测-2026-10-23" aria-label="Permalink to &quot;三、工具（GitHub API 实测，2026-10-23）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>周刊定位</th><th>实测</th><th>能否接入用户现有工作流</th></tr></thead><tbody><tr><td><strong>archify</strong> <code>tt-a1i/archify</code></td><td>一个 <strong>Skill 项目</strong>：把一段话、一个计划、一个代码仓库变成<strong>互动式网页流程图</strong></td><td><strong>★87,779 / fork 5,916 / MIT / JavaScript / 2026-04-15 建，2026-10-23 仍在推</strong>。topics 含 <code>agent-skills</code>、<code>claude-skills</code>、<code>deepseek-harness</code>、<code>dsh-plugin</code></td><td>✅ <strong>本期第一优先</strong>。①本库已有 <code>deepseek-harness-agent-runtime.md</code> + <code>dsh-plugin-ecosystem.md</code>，而已存在移植版 <strong><code>GongYuanCaiJi/dsh-archify</code>（★15，用 JSON 规格生成可验证架构图/流程图/时序图/数据流图）</strong>；②可直接用于<strong>把 weekly/shuju 分析稿里的架构叙事转成图</strong>，也可给 ASF/Field Computation 论文画出交互式架构图。<strong>注意 ★87k 是 skill 生态的现象级数字</strong>（同量级远超本库记录的任何 agent skill）</td></tr><tr><td><strong>sslx</strong> <code>glincker/sslx</code></td><td>检测/查看 HTTPS 证书的命令行工具</td><td>★69 / MIT / <strong>Rust</strong> / 2026-10-21 推送</td><td>✅ 与本期「印度 CA」直接对症；可作为本知识库 website/ 或自托管入口的证书体检脚本</td></tr><tr><td><strong>Mac.apk</strong> <code>kksimp/Mac.apk</code></td><td>让 Mac 跑安卓软件，<strong>非虚拟机非模拟器</strong>，原理是<strong>模拟安卓系统 API</strong></td><td><strong>★2,465</strong> / <strong>AGPL-3.0</strong> / Java / 2026-05-19 建</td><td>⚠️ 思路值得记（<strong>复用 API 层而非重实现整机</strong>，与 #415 的「复用既有接口」同族）；AGPL 需注意；对飞书/安卓端调试有潜在价值</td></tr><tr><td><strong>siltop</strong> <code>CLoaKY233/siltop</code></td><td>macOS 终端实时显示 CPU/GPU/内存/电力/温度/存储/网络</td><td>★50 / Apache-2.0 / Rust / <strong>2026-10-16 建（7 天龄）</strong></td><td>⚠️ 极新。本机跑 cron 任务时可用来盯温度/功耗，但<strong>先观望</strong></td></tr><tr><td><strong>silkpulse</strong> <code>2234839/silkpulse</code></td><td>前端远程调试：插一段脚本即可远程打开该页控制台、接收实时报错，<strong>适合调试手机端页面</strong></td><td>★78 / MIT / TS / 2026-08-09 建</td><td>✅ 有网站/前端产物时（本库 <code>website/</code>）可用</td></tr><tr><td><strong>Parcel</strong> <code>hyphy-void/Parcel</code></td><td>基于 Cloudflare Worker 的临时文件分享，加密链接 + 到期自动清理</td><td>★22 / MIT / TS / <strong>2026-10-06 建（17 天龄）</strong></td><td>⚠️ 极新且体量小。想法可借（CF Worker 做临时投递），生产不建议</td></tr><tr><td><strong>html-to-video</strong> <code>wx4766/html-to-video</code></td><td>把 HTML 网页动画逐帧渲染成 MP4 的命令行工具</td><td>★29 / MIT / JS / <strong>2026-10-11 建（12 天龄）</strong></td><td>⚠️ 极新。若要把 archify 生成的图导出为视频/汇报素材，可先试</td></tr><tr><td><strong>douban-cli</strong> <code>Marvae/douban-cli</code></td><td>豆瓣非官方命令行客户端（电影/剧集/图书数据）</td><td>★70 / MIT / TS / 2026-03-14 建</td><td>⚠️ 与 <code>topics/culture/</code> 的阅读记录采集有弱关联；注意非官方接口稳定性</td></tr><tr><td><strong>wol</strong> <code>Trugamr/wol</code></td><td>命令行/Web 唤醒局域网内休眠的计算机</td><td>★721 / MIT / <strong>Go</strong> / <strong>2026-06-14 最后推送（近 4 个月未动）</strong></td><td>✅ 小工具、单二进制，与本机自托管/远端机器组合可用</td></tr><tr><td><strong>TaskbarLyrics</strong> <code>ANYNC/TaskbarLyrics</code></td><td>Windows 任务栏实时显示歌词</td><td>★501 / MIT / C# / 2026-02-13 建</td><td>❌ 非本机平台</td></tr><tr><td><strong>Pines</strong> <code>thedevdojo/pines</code></td><td>基于 Tailwind 的 UI 组件库</td><td>★3,335 / MIT / HTML / <strong>2025-08-23 最后推送（已停更约 1 年）</strong></td><td>⚠️ star 高但<strong>近一年无提交</strong>，选型需谨慎</td></tr><tr><td><strong>Little Snitch Mini</strong></td><td>macOS 显示所有应用的联网连接并可阻断单条连接</td><td>商业软件（obdev.at，非开源）</td><td>✅ 安全侧刚需场景（想知道哪个进程在偷偷联网）；替代品可看 <code>LuLu</code>（开源）</td></tr><tr><td><strong>Learn-Vim</strong> <code>iggredible/Learn-Vim</code></td><td>开源 Vim 教程（另有中文版）</td><td><strong>★15,270</strong> / <strong>NOASSERTION</strong>（许可证需自行确认） / 2026-09-07 推送</td><td>✅ 教程类，语音/文本学习资源。<strong>注意许可证未标准化</strong></td></tr></tbody></table><p><strong>工具判断</strong>：本期真正的「钩子」只有一个——<strong>archify</strong>。它同时命中了三件本库正在做的事：<strong>agent skill 形态</strong>、DSH 插件生态、以及「把分析稿变成可视图」。其余工具里，<strong>sslx / silkpulse / wol 三个是能干活的</strong>，<code>siltop / Parcel / html-to-video</code> 三个是<strong>7–17 天龄的极新项目，先借思路</strong>；<code>Pines</code> 是<strong>高 star 但停更</strong>的典型陷阱；<code>Learn-Vim</code> 的许可证是 <strong>NOASSERTION</strong>，引用时要注明。</p><hr><h2 id="四、资源" tabindex="-1">四、资源 <a class="header-anchor" href="#四、资源" aria-label="Permalink to &quot;四、资源&quot;">​</a></h2><ol><li><strong>大鹏书法</strong>（zidian.dapengshufa.com）——查某字的各种书法写法。</li><li><strong>Learn Vim</strong>（<code>iggredible/Learn-Vim</code>，★15,270，中文版在 GitLab）——面向「Vim 很陡」这个长期痛点。</li><li><strong>编译器和语言设计导论</strong>（dthain.github.io/books/compiler/）——免费英文教材，面向初学者，讲概念 + <strong>如何写一个 C 编译器</strong>。</li></ol><p><strong>我的评注</strong>：第 3 条与本期工具表的 archify、以及 <code>topics/ai-system-architecture/</code> 里 ASF/Field Computation 的「从零设计一种计算范式」是同一条精神线——<strong>写编译器是理解抽象层最暴力的方法</strong>（先造出来，才知道哪层该在哪层）。在「AI 能生成一切」的语境下，<strong>这类「亲自把东西造一遍」的资源反而是抗贬值的</strong>：它训练的是判断力，不是产出。</p><hr><h2 id="五、言论与文摘" tabindex="-1">五、言论与文摘 <a class="header-anchor" href="#五、言论与文摘" aria-label="Permalink to &quot;五、言论与文摘&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>内容</th><th>我的判断</th></tr></thead><tbody><tr><td>1</td><td>有人问「AI 写的代码我不理解，公司却要我发布」，HN 读者答：<strong>「不要让 AI 设计代码，而要让它实现你已经设计好的代码。」</strong></td><td>本期最有价值的一句，也是与主文一<strong>互相拆台</strong>的一句（详见主文一评注 4）。<strong>可升格为本库工作原则</strong>：AI 负责实现，人保留设计权</td></tr><tr><td>2</td><td>「大多数建议对于给出建议的人都是正确的，对于别人就不一定了。」（coached.com）</td><td>与 <code>topics/career-observation/</code> 的「收入 ≠ 财富」同型：<strong>给建议的人暴露的是自己的处境</strong></td></tr><tr><td>3</td><td>「AI 让单人创业变得容易，<strong>创业失败的主要原因以后将是孤独</strong>……AI 或许可以帮助你更快地前进，但它无法完全取代与人倾诉或分享喜悦。」（Every，Julian Weisser）</td><td>与本人正在做的「单人 + AI 外脑」模式直接相关；也是 <code>topics/entrepreneurship/</code> 该补的一条：<strong>瓶颈从能力转向关系</strong></td></tr><tr><td>4</td><td>美国政府的主要关注已变成「如何保持对中国的技术领先优势，以及设法维持美国股市的高股价」。（《经济学家》）</td><td>与本期主文二（Hirundo 指控 Qwen）互为语境：<strong>当竞争被定义为国家级，技术报告就成了政治材料</strong>。库内 <code>global-finance/</code>、<code>ai-industry-2026-q3-knowledge.md</code> 可连</td></tr><tr><td>5</td><td>OpenAI 数月内发布数百项 AI 数学证明震惊数学界，有数学家说他不禁哭了；《我知道数学家为何哭泣》答：<strong>「数学不会在意你的感受，科学现实对你的眼泪漠不关心。」</strong></td><td>与陶哲轩篇同轴（见二.2）。<strong>这是 2026 年最典型的两种反应</strong>：悲悼 vs 达尔文式劝勉。两者都不涉及「人还要不要理解」这个真问题</td></tr><tr><td>文摘</td><td><strong>眯眼为什么看得更清</strong>：不是挤压晶状体，而是<strong>减少进光量、让光线集中于视野中心（针孔效应）</strong>；眯眼不损害视力，<strong>它是视力下降的症状，不是原因</strong></td><td>反直觉机制的标准模板。可迁移的判断法：<strong>先找被忽略的那个物理量</strong></td></tr></tbody></table><hr>',52)])])}const m=o(e,[["render",d]]);export{u as __pageData,m as default};
